## 10. Hands-On: SearchCriteriaBuilder in Practice

### Querying Products in local-instance

```php
<?php
// Try in a custom command, controller, or the Magento 2 Tinker equivalent

use Magento\Catalog\Api\ProductRepositoryInterface;
use Magento\Framework\Api\SearchCriteriaBuilder;
use Magento\Framework\Api\FilterBuilder;
use Magento\Framework\Api\SortOrderBuilder;

class ProductSearchExample
{
    public function __construct(
        private readonly ProductRepositoryInterface $productRepository,
        private readonly SearchCriteriaBuilder $searchCriteriaBuilder,
        private readonly FilterBuilder $filterBuilder,
        private readonly SortOrderBuilder $sortOrderBuilder,
    ) {}

    public function execute(): void
    {
        // --- Example 1: Products with price between 10 and 100, active, sorted by name ---

        $sortOrder = $this->sortOrderBuilder
            ->setField('name')
            ->setAscendingDirection()
            ->create();

        $searchCriteria = $this->searchCriteriaBuilder
            ->addFilter('price', 10, 'gteq')
            ->addFilter('price', 100, 'lteq')
            ->addFilter('status', 1, 'eq')    // 1 = enabled
            ->addSortOrder($sortOrder)
            ->setPageSize(5)
            ->setCurrentPage(1)
            ->create();

        $searchResults = $this->productRepository->getList($searchCriteria);

        echo "Total matching products: " . $searchResults->getTotalCount() . PHP_EOL;
        echo "Returned on this page: " . count($searchResults->getItems()) . PHP_EOL;

        foreach ($searchResults->getItems() as $product) {
            printf(
                "  [%d] %-40s $%.2f  SKU: %s\n",
                $product->getId(),
                $product->getName(),
                $product->getPrice(),
                $product->getSku()
            );
        }

        // --- Example 2: Inspect the SearchResults object structure ---

        echo PHP_EOL . "SearchResults class: " . get_class($searchResults) . PHP_EOL;
        echo "Implements SearchResultsInterface: " . (
            $searchResults instanceof \Magento\Framework\Api\SearchResultsInterface
            ? 'YES' : 'NO'
        ) . PHP_EOL;

        // Echo back the search criteria
        $returnedCriteria = $searchResults->getSearchCriteria();
        echo "Page size: " . $returnedCriteria->getPageSize() . PHP_EOL;
        echo "Current page: " . $returnedCriteria->getCurrentPage() . PHP_EOL;

        foreach ($returnedCriteria->getFilterGroups() as $groupIndex => $filterGroup) {
            echo "Filter Group $groupIndex (OR within group):" . PHP_EOL;
            foreach ($filterGroup->getFilters() as $filter) {
                printf(
                    "  field=%s  condition=%s  value=%s\n",
                    $filter->getField(),
                    $filter->getConditionType(),
                    $filter->getValue()
                );
            }
        }

        // --- Example 3: OR query — products with SKU starting with 'WS' or 'WP' ---

        $wsFilter = $this->filterBuilder
            ->setField('sku')
            ->setValue('WS%')
            ->setConditionType('like')
            ->create();

        $wpFilter = $this->filterBuilder
            ->setField('sku')
            ->setValue('WP%')
            ->setConditionType('like')
            ->create();

        $orCriteria = $this->searchCriteriaBuilder
            ->addFilters([$wsFilter, $wpFilter])   // OR: sku LIKE 'WS%' OR sku LIKE 'WP%'
            ->setPageSize(10)
            ->create();

        $orResults = $this->productRepository->getList($orCriteria);
        echo PHP_EOL . "OR query results: " . $orResults->getTotalCount() . PHP_EOL;
    }
}
```

