## 9. Hands-On: Load a Configurable Product & Its Children

### Setup: Standalone Script for local-instance

```php
<?php
/**
 * File: load_configurable.php
 * Run from Magento root: php load_configurable.php
 *
 * Demonstrates:
 * - Loading a configurable product via ProductRepositoryInterface
 * - Loading child simples via separate getList() call
 * - Inspecting configurable options (attributes)
 * - Comparing getUsedProducts() vs repository approach
 */

use Magento\Framework\App\Bootstrap;

require __DIR__ . '/app/bootstrap.php';

$bootstrap = Bootstrap::create(BP, $_SERVER);
$objectManager = $bootstrap->getObjectManager();

// Set area code (required for some operations)
$state = $objectManager->get(\Magento\Framework\App\State::class);
$state->setAreaCode(\Magento\Framework\App\Area::AREA_FRONTEND);

// ============================================================
// DEPENDENCIES
// ============================================================
/** @var \Magento\Catalog\Api\ProductRepositoryInterface $productRepository */
$productRepository = $objectManager->get(\Magento\Catalog\Api\ProductRepositoryInterface::class);

/** @var \Magento\Framework\Api\SearchCriteriaBuilder $searchCriteriaBuilder */
$searchCriteriaBuilder = $objectManager->get(\Magento\Framework\Api\SearchCriteriaBuilder::class);

/** @var \Magento\ConfigurableProduct\Model\Product\Type\Configurable $configurableType */
$configurableType = $objectManager->get(
    \Magento\ConfigurableProduct\Model\Product\Type\Configurable::class
);

// ============================================================
// STEP 1: LOAD THE CONFIGURABLE PARENT
// ============================================================
$configurableSku = 'MH01'; // Replace with actual SKU from your sandbox

try {
    $parent = $productRepository->get($configurableSku);
} catch (\Magento\Framework\Exception\NoSuchEntityException $e) {
    die('Product not found: ' . $e->getMessage() . PHP_EOL);
}

echo '=== CONFIGURABLE PRODUCT ===' . PHP_EOL;
echo 'SKU:         ' . $parent->getSku() . PHP_EOL;
echo 'Name:        ' . $parent->getName() . PHP_EOL;
echo 'Type:        ' . $parent->getTypeId() . PHP_EOL;
echo 'Entity ID:   ' . $parent->getId() . PHP_EOL;
echo 'Status:      ' . $parent->getStatus() . PHP_EOL;
echo 'Visibility:  ' . $parent->getVisibility() . PHP_EOL;
echo PHP_EOL;

// ============================================================
// STEP 2: INSPECT CONFIGURABLE OPTIONS (Attributes)
// ============================================================
$extensionAttributes = $parent->getExtensionAttributes();

echo '=== CONFIGURABLE OPTIONS (Attribute Configuration) ===' . PHP_EOL;
$configurableOptions = $extensionAttributes->getConfigurableProductOptions() ?? [];

foreach ($configurableOptions as $option) {
    echo 'Attribute: ' . $option->getLabel()
        . ' (ID: ' . $option->getAttributeId() . ')' . PHP_EOL;

    foreach ($option->getValues() as $value) {
        echo '  - Option Value Index: ' . $value->getValueIndex() . PHP_EOL;
    }
}
echo PHP_EOL;

// ============================================================
// STEP 3: GET CHILD IDs (they are NOT embedded — just IDs)
// ============================================================
$childIds = $extensionAttributes->getConfigurableProductLinks() ?? [];

echo '=== CHILD PRODUCT IDs ===' . PHP_EOL;
echo 'IDs: ' . implode(', ', $childIds) . PHP_EOL;
echo 'Count: ' . count($childIds) . PHP_EOL;
echo PHP_EOL;

// ============================================================
// STEP 4: LOAD CHILDREN VIA getList() (SEPARATE CALL — KEY POINT)
// ============================================================
echo '=== METHOD 1: Load Children via Repository::getList() ===' . PHP_EOL;

if (!empty($childIds)) {
    $searchCriteria = $searchCriteriaBuilder
        ->addFilter('entity_id', $childIds, 'in')
        ->create();

    $childResults = $productRepository->getList($searchCriteria);
    $children = $childResults->getItems();

    echo 'Children found: ' . count($children) . PHP_EOL . PHP_EOL;

    foreach ($children as $child) {
