        echo '  Size:       ' . ($sizeAttr  ? $sizeAttr->getValue()  : 'N/A') . PHP_EOL;

        // Show media gallery
        $mediaEntries = $child->getMediaGalleryEntries() ?? [];
        echo '  Images:     ' . count($mediaEntries) . PHP_EOL;
        echo PHP_EOL;
    }
}

// ============================================================
// STEP 5: ALTERNATIVE — Load Children via Type Instance
// ============================================================
