/** @var \Magento\Catalog\Model\Product $parentModel */
$parentModel = $parent; // ProductInterface is implemented by Product model

$usedProducts = $parentModel->getTypeInstance()->getUsedProducts($parentModel);

echo 'Children found: ' . count($usedProducts) . PHP_EOL . PHP_EOL;

