## 10. Hands-On: Programmatic Order Creation

### 10.1 Complete Example — Guest Order via CartManagementInterface

This is the hands-on exercise for the local-instance environment.

```php
<?php
declare(strict_types=1);

namespace Vendor\Module\Model;

use Magento\Catalog\Api\ProductRepositoryInterface;
use Magento\Framework\Exception\LocalizedException;
use Magento\Quote\Api\CartItemRepositoryInterface;
use Magento\Quote\Api\CartManagementInterface;
use Magento\Quote\Api\CartRepositoryInterface;
use Magento\Quote\Api\Data\AddressInterfaceFactory;
use Magento\Quote\Api\Data\CartItemInterfaceFactory;
use Magento\Quote\Api\Data\PaymentInterfaceFactory;
use Magento\Store\Model\StoreManagerInterface;

class ProgrammaticOrderCreator
{
    public function __construct(
        private readonly CartManagementInterface $cartManagement,
        private readonly CartRepositoryInterface $cartRepository,
        private readonly CartItemRepositoryInterface $cartItemRepository,
        private readonly CartItemInterfaceFactory $cartItemFactory,
        private readonly AddressInterfaceFactory $addressFactory,
        private readonly PaymentInterfaceFactory $paymentFactory,
        private readonly ProductRepositoryInterface $productRepository,
        private readonly StoreManagerInterface $storeManager,
    ) {}

    /**
     * Creates a complete order programmatically as a guest customer.
     *
     * @param string $sku     The product SKU to add to the cart
     * @param float  $qty     The quantity to order
     * @return int            The new order entity_id
     * @throws LocalizedException
     */
    public function createGuestOrder(string $sku, float $qty = 1.0): int
    {
        // ------------------------------------------------------------------
        // STEP 1: Create an empty guest cart
        // ------------------------------------------------------------------
        $cartId = $this->cartManagement->createEmptyCart();
        $quote  = $this->cartRepository->get($cartId);

        // Set the store (required for price/tax calculations)
        $storeId = $this->storeManager->getStore()->getId();
        $quote->setStoreId($storeId);
        $quote->setIsActive(true);
        $quote->setIsMultiShipping(false);

        // ------------------------------------------------------------------
        // STEP 2: Add a product to the cart
        // ------------------------------------------------------------------
        $cartItem = $this->cartItemFactory->create();
        $cartItem->setQuoteId($cartId);
        $cartItem->setSku($sku);
        $cartItem->setQty($qty);
        $cartItem->setProductType(\Magento\Catalog\Model\Product\Type::TYPE_SIMPLE);

        $this->cartItemRepository->save($cartItem);

        // ------------------------------------------------------------------
        // STEP 3: Set billing address
        // ------------------------------------------------------------------
        $billingAddress = $this->addressFactory->create();
        $billingAddress->setFirstname('John');
        $billingAddress->setLastname('Doe');
        $billingAddress->setStreet(['123 Main Street']);
        $billingAddress->setCity('Beverly Hills');
        $billingAddress->setRegionId(12);      // California region ID
        $billingAddress->setRegionCode('CA');
        $billingAddress->setPostcode('90210');
        $billingAddress->setCountryId('US');
        $billingAddress->setTelephone('555-867-5309');
        $billingAddress->setEmail('john.doe@example.com');
        $billingAddress->setSaveInAddressBook(0);

        $quote->setBillingAddress($billingAddress);

        // ------------------------------------------------------------------
        // STEP 4: Set shipping address and method
        // ------------------------------------------------------------------
        $shippingAddress = $this->addressFactory->create();
        $shippingAddress->setFirstname('John');
        $shippingAddress->setLastname('Doe');
        $shippingAddress->setStreet(['123 Main Street']);
        $shippingAddress->setCity('Beverly Hills');
        $shippingAddress->setRegionId(12);
        $shippingAddress->setRegionCode('CA');
        $shippingAddress->setPostcode('90210');
        $shippingAddress->setCountryId('US');
        $shippingAddress->setTelephone('555-867-5309');
        $shippingAddress->setEmail('john.doe@example.com');
        $shippingAddress->setSaveInAddressBook(0);

        $shippingQuoteAddress = $quote->getShippingAddress();
        $shippingQuoteAddress->importDataObject($shippingAddress);
        $shippingQuoteAddress->setCollectShippingRates(true);
        $shippingQuoteAddress->collectShippingRates();
        // Format: {carrier_code}_{method_code}
        $shippingQuoteAddress->setShippingMethod('flatrate_flatrate');

        // ------------------------------------------------------------------
        // STEP 5: Set payment method
        // ------------------------------------------------------------------
        $payment = $this->paymentFactory->create();
        $payment->setMethod('checkmo'); // Check/Money Order (offline, safe for testing)

        $quote->setPaymentMethod('checkmo');
        $quote->setInventoryProcessed(false);
        $quote->getPayment()->importData(['method' => 'checkmo']);

        // ------------------------------------------------------------------
        // STEP 6: Set guest customer data
        // ------------------------------------------------------------------
        $quote->setCustomerEmail('john.doe@example.com');
        $quote->setCustomerFirstname('John');
        $quote->setCustomerLastname('Doe');
        $quote->setCustomerIsGuest(true);
        $quote->setCustomerGroupId(\Magento\Customer\Model\Group::NOT_LOGGED_IN_ID);

        // ------------------------------------------------------------------
        // STEP 7: Collect totals and save the quote
        // ------------------------------------------------------------------
        $quote->collectTotals();
        $this->cartRepository->save($quote);

        // ------------------------------------------------------------------
        // STEP 8: Place the order
        // placeOrder() validates everything and converts quote to order
        // Returns the new order entity_id
        // ------------------------------------------------------------------
        $orderId = $this->cartManagement->placeOrder($cartId);

        return (int)$orderId;
    }
}
```

### 10.2 Customer Order Variant

```php
<?php
declare(strict_types=1);

namespace Vendor\Module\Model;

use Magento\Customer\Api\CustomerRepositoryInterface;
use Magento\Quote\Api\CartItemRepositoryInterface;
use Magento\Quote\Api\CartManagementInterface;
use Magento\Quote\Api\CartRepositoryInterface;
use Magento\Quote\Api\Data\CartItemInterfaceFactory;

class ProgrammaticCustomerOrderCreator
{
    public function __construct(
        private readonly CartManagementInterface $cartManagement,
        private readonly CartRepositoryInterface $cartRepository,
        private readonly CartItemRepositoryInterface $cartItemRepository,
        private readonly CartItemInterfaceFactory $cartItemFactory,
        private readonly CustomerRepositoryInterface $customerRepository,
    ) {}

    public function createCustomerOrder(int $customerId, string $sku, float $qty = 1.0): int
    {
        $customer = $this->customerRepository->getById($customerId);

        // Create cart for logged-in customer
        $cartId = $this->cartManagement->createEmptyCartForCustomer($customerId);
        $quote  = $this->cartRepository->get($cartId);

        // Add product
        $cartItem = $this->cartItemFactory->create();
        $cartItem->setQuoteId($cartId);
        $cartItem->setSku($sku);
        $cartItem->setQty($qty);
        $cartItem->setProductType(\Magento\Catalog\Model\Product\Type::TYPE_SIMPLE);
        $this->cartItemRepository->save($cartItem);

        // Use customer's default shipping/billing addresses
        $shippingAddress = $quote->getShippingAddress();
        $shippingAddress->setCollectShippingRates(true);
        $shippingAddress->collectShippingRates();
        $shippingAddress->setShippingMethod('flatrate_flatrate');

        // Set payment
        $quote->setPaymentMethod('checkmo');
        $quote->getPayment()->importData(['method' => 'checkmo']);

        $quote->collectTotals();
        $this->cartRepository->save($quote);

        return (int)$this->cartManagement->placeOrder($cartId);
    }
}
