        } catch (\Exception $e) {
            $output->writeln("<error>Error: {$e->getMessage()}</error>");
            return Command::FAILURE;
        }
    }
}
```

```bash
# Run in local-instance
bin/magento vendor:order:create-test MH01-XS-Black 2
```

