### 9.7 Repository Implementation

```php
<?php
// Model/ArticleRepository.php

declare(strict_types=1);

namespace Vendor\Module\Model;

use Magento\Framework\Api\SearchCriteria\CollectionProcessorInterface;
use Magento\Framework\Api\SearchCriteriaInterface;
use Magento\Framework\Exception\CouldNotDeleteException;
use Magento\Framework\Exception\CouldNotSaveException;
use Magento\Framework\Exception\NoSuchEntityException;
use Vendor\Module\Api\ArticleRepositoryInterface;
use Vendor\Module\Api\Data\ArticleInterface;
use Vendor\Module\Api\Data\ArticleInterfaceFactory;
use Vendor\Module\Api\Data\ArticleSearchResultsInterface;
use Vendor\Module\Api\Data\ArticleSearchResultsInterfaceFactory;
use Vendor\Module\Model\ResourceModel\Article as ArticleResourceModel;
use Vendor\Module\Model\ResourceModel\Article\CollectionFactory;

class ArticleRepository implements ArticleRepositoryInterface
{
    public function __construct(
        private readonly ArticleResourceModel $resourceModel,
        private readonly ArticleInterfaceFactory $articleFactory,
        private readonly CollectionFactory $collectionFactory,
        private readonly ArticleSearchResultsInterfaceFactory $searchResultsFactory,
        private readonly CollectionProcessorInterface $collectionProcessor
    ) {}

    /**
     * Load by ID — uses ResourceModel::load() internally.
     */
    public function getById(int $id): ArticleInterface
    {
        /** @var Article $article */
        $article = $this->articleFactory->create();
        $this->resourceModel->load($article, $id);

        if (!$article->getId()) {
            throw new NoSuchEntityException(
                __('Article with ID "%1" does not exist.', $id)
            );
        }

        return $article;
    }

    /**
     * Save — uses ResourceModel::save() which manages INSERT/UPDATE.
     */
    public function save(ArticleInterface $article): ArticleInterface
    {
        try {
            $this->resourceModel->save($article);
        } catch (\Exception $e) {
            throw new CouldNotSaveException(
                __('Could not save article: %1', $e->getMessage()),
                $e
            );
        }

        return $article;
    }

    /**
     * Delete entity by object reference.
     */
    public function delete(ArticleInterface $article): bool
    {
        try {
            $this->resourceModel->delete($article);
        } catch (\Exception $e) {
            throw new CouldNotDeleteException(
                __('Could not delete article: %1', $e->getMessage()),
                $e
            );
        }

        return true;
    }

    /**
     * Delete entity by ID — load first, then delete.
     */
    public function deleteById(int $id): bool
    {
        return $this->delete($this->getById($id));
    }

    /**
     * List entities with filtering, sorting, and pagination via SearchCriteria.
     */
    public function getList(SearchCriteriaInterface $searchCriteria): ArticleSearchResultsInterface
    {
        $collection = $this->collectionFactory->create();

        // CollectionProcessor applies filters, sort orders, and pagination
        // from SearchCriteria to the Collection automatically
        $this->collectionProcessor->process($searchCriteria, $collection);

        $searchResults = $this->searchResultsFactory->create();
        $searchResults->setSearchCriteria($searchCriteria);
        $searchResults->setItems($collection->getItems());
        $searchResults->setTotalCount($collection->getSize());

        return $searchResults;
    }
}
```

- **Exam focus:** The repository calls `$this->resourceModel->save($article)` — **not** `$article->save()`. The resource model's `save()` method is different from the model's `save()` method.
- **Exam focus:** `CollectionProcessorInterface::process()` applies all SearchCriteria filters, sort orders, and page settings to the collection in one call.

