## 10. Data Patches with ProductRepository

### 10.1 What Is a Data Patch?

Data Patches are classes that run **once** during `setup:upgrade` to modify data in the database. They replace the deprecated `InstallData` / `UpgradeData` scripts.

```
Vendor/Module/Setup/Patch/Data/
  UpdateProductDescriptions.php   <-- Implements DataPatchInterface
```

- **Exam focus:** Data patches implement `Magento\Framework\Setup\Patch\DataPatchInterface` and run exactly once (tracked in `patch_list` table). They are irreversible by default unless you implement `Magento\Framework\Setup\Patch\PatchRevertableInterface` (note: the interface name is `PatchRevertableInterface`, NOT `RevertableDataPatchInterface`).

### 10.2 Full Data Patch Example — Update Products via ProductRepository

```php
<?php
// Setup/Patch/Data/UpdateProductDescriptions.php

declare(strict_types=1);

namespace Vendor\Module\Setup\Patch\Data;

use Magento\Catalog\Api\Data\ProductInterface;
use Magento\Catalog\Api\ProductRepositoryInterface;
use Magento\Framework\Api\SearchCriteriaBuilder;
use Magento\Framework\App\State;
use Magento\Framework\Exception\LocalizedException;
use Magento\Framework\Setup\ModuleDataSetupInterface;
use Magento\Framework\Setup\Patch\DataPatchInterface;
use Magento\Store\Model\StoreManagerInterface;
use Psr\Log\LoggerInterface;

class UpdateProductDescriptions implements DataPatchInterface
{
    public function __construct(
        private readonly ModuleDataSetupInterface $moduleDataSetup,
        private readonly ProductRepositoryInterface $productRepository,
        private readonly SearchCriteriaBuilder $searchCriteriaBuilder,
        private readonly StoreManagerInterface $storeManager,
        private readonly State $appState,
        private readonly LoggerInterface $logger
    ) {}

    /**
     * Apply the patch — runs once on setup:upgrade.
     */
    public function apply(): self
    {
        // Data patches run in CLI context — area must be set explicitly
        // to avoid "Area code not set" errors when loading products
        $this->appState->emulateAreaCode(
            \Magento\Framework\App\Area::AREA_ADMINHTML,
            function () {
                $this->executeUpdate();
            }
        );

        return $this;
    }

    private function executeUpdate(): void
    {
        // Use admin store to load/save without store-specific scope issues
        $this->storeManager->setCurrentStore(\Magento\Store\Model\Store::DEFAULT_STORE_ID);

        // Build search criteria to find products needing update
        $searchCriteria = $this->searchCriteriaBuilder
            ->addFilter(ProductInterface::STATUS, 1)                          // enabled
            ->addFilter('type_id', 'simple')                                  // simple products
            ->addFilter('description', null, 'null')                          // missing description
            ->setPageSize(100)                                                 // process in batches
            ->setCurrentPage(1)
            ->create();

        $results = $this->productRepository->getList($searchCriteria);
        $totalCount = $results->getTotalCount();

        $this->logger->info(
            sprintf('UpdateProductDescriptions: Found %d products to update.', $totalCount)
        );

        // Process all pages
        $totalPages = (int) ceil($totalCount / 100);

        for ($page = 1; $page <= $totalPages; $page++) {
            $searchCriteria = $this->searchCriteriaBuilder
                ->addFilter(ProductInterface::STATUS, 1)
                ->addFilter('type_id', 'simple')
                ->addFilter('description', null, 'null')
                ->setPageSize(100)
                ->setCurrentPage($page)
                ->create();

            $products = $this->productRepository->getList($searchCriteria)->getItems();

            foreach ($products as $product) {
                try {
                    $product->setDescription(
                        sprintf(
                            '<p>%s is a high-quality product available at our store.</p>',
                            htmlspecialchars($product->getName())
                        )
                    );

                    // Use repository save — not $product->save()!
                    $this->productRepository->save($product);

                    $this->logger->info(
                        sprintf('Updated description for SKU: %s', $product->getSku())
                    );
                } catch (LocalizedException $e) {
                    $this->logger->error(
                        sprintf(
                            'Failed to update SKU %s: %s',
                            $product->getSku(),
                            $e->getMessage()
                        )
                    );
                    // Continue with next product rather than failing entire patch
                }
            }
        }
    }

    /**
     * Define patch dependencies — this patch runs after listed patches complete.
     */
    public static function getDependencies(): array
    {
        return [
            // e.g., \Vendor\Module\Setup\Patch\Data\CreateCustomAttribute::class
        ];
    }

    /**
     * Aliases allow renaming patches without re-running them.
     */
    public function getAliases(): array
    {
        return [];
    }
}
```

### 10.3 Simpler Data Patch Pattern — Direct SKU Targeting

```php
<?php
// Setup/Patch/Data/FixSpecificProductPrices.php

declare(strict_types=1);

namespace Vendor\Module\Setup\Patch\Data;

use Magento\Catalog\Api\ProductRepositoryInterface;
use Magento\Framework\App\State;
use Magento\Framework\Setup\Patch\DataPatchInterface;

class FixSpecificProductPrices implements DataPatchInterface
{
    // Products to update: [sku => price]
    private const PRICE_CORRECTIONS = [
        'PROD-001' => 19.99,
        'PROD-002' => 29.99,
        'PROD-003' => 39.99,
    ];

    public function __construct(
        private readonly ProductRepositoryInterface $productRepository,
        private readonly State $appState
    ) {}

    public function apply(): self
    {
        $this->appState->emulateAreaCode(
            \Magento\Framework\App\Area::AREA_ADMINHTML,
            function () {
                foreach (self::PRICE_CORRECTIONS as $sku => $price) {
                    try {
                        $product = $this->productRepository->get($sku);
                        $product->setPrice($price);
                        $this->productRepository->save($product);
                    } catch (\Magento\Framework\Exception\NoSuchEntityException $e) {
                        // Skip non-existent products silently
                    }
                }
            }
        );

        return $this;
    }

    public static function getDependencies(): array
    {
        return [];
    }

    public function getAliases(): array
    {
        return [];
    }
}
```

### 10.4 Running Data Patches

```bash
# Apply all pending data patches
bin/magento setup:upgrade

# Check database status (including pending patches)
bin/magento setup:db:status

# NOTE: There is NO "patch:status" command in Magento 2.
# The patch_list table tracks which patches have been applied:
# SELECT * FROM patch_list WHERE type = 'data';
```

- **Exam focus:** Data patches are tracked in the `patch_list` table. If a patch class is in `patch_list`, it will **never run again** even if the code changes. To force a re-run during development, delete the row from `patch_list`.

